-- SOMENTE banco descartável. Recorte estrutural das dependências reais, sem dados de produção.
DO $$ BEGIN IF current_database()<>'membros_test' THEN RAISE EXCEPTION 'Banco de teste obrigatório'; END IF; END $$;
CREATE ROLE anon NOLOGIN;
CREATE ROLE authenticated NOLOGIN;
CREATE ROLE service_role NOLOGIN BYPASSRLS;
CREATE SCHEMA auth;
CREATE SCHEMA storage;
GRANT USAGE ON SCHEMA public,auth,storage TO anon,authenticated,service_role;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT NULLIF(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql STABLE AS $$ SELECT NULLIF(current_setting('request.jwt.claim.role',true),'') $$;
CREATE TABLE auth.users(id uuid PRIMARY KEY,email text,email_confirmed_at timestamptz,is_anonymous boolean DEFAULT false,raw_user_meta_data jsonb DEFAULT '{}');
CREATE TYPE public.app_role AS ENUM('admin','client','design','traffic','manager');
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id),email text,full_name text,company_name text);
CREATE TABLE public.user_roles(id uuid DEFAULT gen_random_uuid(),user_id uuid REFERENCES auth.users(id),role public.app_role,UNIQUE(user_id,role));
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE FUNCTION public.is_staff(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role IN ('admin','design','traffic','manager')) $$;
CREATE TABLE public.team_client_assignments(user_id uuid,client_id uuid);
CREATE FUNCTION public.can_access_client(_client_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT auth.uid() IS NOT NULL AND (public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'client') AND auth.uid()=_client_id) OR (public.is_staff(auth.uid()) AND EXISTS(SELECT 1 FROM public.team_client_assignments WHERE user_id=auth.uid() AND client_id=_client_id))) $$;
CREATE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN RETURN NEW; END $$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE TABLE public.financial_plans(id uuid PRIMARY KEY,name text,is_active boolean DEFAULT true);
CREATE TABLE public.financial_plan_versions(id uuid PRIMARY KEY,plan_id uuid REFERENCES public.financial_plans(id));
CREATE TABLE public.financial_client_terms(id uuid PRIMARY KEY,client_id uuid REFERENCES public.profiles(id),plan_version_id uuid REFERENCES public.financial_plan_versions(id),status text,starts_on date,ends_on date);
CREATE TABLE public.vendas_integracoes(id uuid PRIMARY KEY,client_id uuid REFERENCES public.profiles(id),gateway text,chave text,ativo boolean DEFAULT true);
CREATE TABLE public.vendas_eventos(id uuid PRIMARY KEY,integracao_id uuid REFERENCES public.vendas_integracoes(id),produto_externo_id text,id_externo text);
CREATE TABLE public.projects(id uuid PRIMARY KEY,client_id uuid REFERENCES public.profiles(id));
CREATE TABLE public.documents(id uuid PRIMARY KEY,client_id uuid REFERENCES public.profiles(id),content text);
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.financial_client_terms ENABLE ROW LEVEL SECURITY;
GRANT SELECT ON public.profiles,public.user_roles,public.projects,public.documents,public.financial_plans,public.financial_plan_versions,public.financial_client_terms,public.vendas_integracoes,public.vendas_eventos TO authenticated;
CREATE POLICY profile_le ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_staff(auth.uid()));
CREATE POLICY role_le ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_staff(auth.uid()));
CREATE POLICY projeto_le ON public.projects FOR SELECT TO authenticated USING(public.can_access_client(client_id));
CREATE POLICY documento_le ON public.documents FOR SELECT TO authenticated USING(public.can_access_client(client_id));
CREATE POLICY termo_le ON public.financial_client_terms FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager'));
CREATE TABLE storage.buckets(id text PRIMARY KEY,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
CREATE TABLE storage.objects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bucket_id text REFERENCES storage.buckets(id),name text);
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE,DELETE ON storage.objects TO authenticated,anon;
-- Permissiva intencionalmente ampla no teste: a nova barreira deve prevalecer.
CREATE POLICY legado_amplo ON storage.objects FOR ALL TO authenticated,anon USING(true) WITH CHECK(true);
